 // DeleteExpiredKeys scan the entire index in ascending order to delete expired keys.
+// The bufferSize parameter specifies the number of keys to process in each iteration.
+// If bufferSize is 0, it defaults to 100.
 // It is a time-consuming operation, so we need to specify a timeout
 // to prevent the DB from being unavailable for a long time.
-func (db *DB) DeleteExpiredKeys(timeout time.Duration) error {
+func (db *DB) DeleteExpiredKeys(timeout time.Duration, bufferSize int) error {
+	// bufferSize specifies the number of keys to process in each iteration.
+	// If bufferSize is 0, it defaults to 100.
 	// set timeout
 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
 	defer cancel()
 	done := make(chan struct{}, 1)

 	var innerErr error
+
+	if bufferSize <= 0 {
+		bufferSize = 100
+	}
 	now := time.Now().UnixNano()
 	go func(ctx context.Context) {
 		db.mu.Lock()
 		defer db.mu.Unlock()
 		for {
 			// select 100 keys from the db.index
-			positions := make([]*wal.ChunkPosition, 0, 100)
+			positions := make([]*wal.ChunkPosition, 0, bufferSize)
 			db.index.AscendGreaterOrEqual(db.expiredCursorKey, func(k []byte, pos *wal.ChunkPosition) (bool, error) {
 				positions = append(positions, pos)
-				if len(positions) >= 100 {
+				if len(positions) >= bufferSize {
 					return false, nil
 				}
 				return true, nil
