```bash
sed -i '/func (db \*DB) DeleteExpiredKeys(timeout time.Duration) error {/a\	// bufferSize specifies the number of keys to process in each iteration.
	// If bufferSize is 0, it defaults to 100.' db.go && sed -i 's/positions := make(\[\]\*wal.ChunkPosition, 0, 100)/positions := make(\[\]\*wal.ChunkPosition, 0, bufferSize)/' db.go && sed -i 's/func (db \*DB) DeleteExpiredKeys(timeout time.Duration) error {/func (db \*DB) DeleteExpiredKeys(timeout time.Duration, bufferSize int) error {/' db.go && sed -i 's/if len(positions) >= 100/if len(positions) >= bufferSize/' db.go && sed -i 's/var innerErr error/var innerErr error

	if bufferSize <= 0 {
		bufferSize = 100
	}/' db.go
```

